{"hypotheses": [
  {
    "root_cause": "service:gridcast:grid-telemetry",
    "mechanism": "The external demand telemetry feed stopped sending valid demand records or changed its schema/format without notice, causing ingestion to reject demand data.",
    "statement": "Upstream demand telemetry outage or schema change."
  },
  {
    "root_cause": "service:gridcast:ingestion / k8s:gridcast:deployment:ingestion",
    "mechanism": "A faulty rollout, configuration change, or resource exhaustion inside the ingestion service caused demand data processing to fail.",
    "statement": "Ingestion service internal fault."
  },
  {
    "root_cause": "service:gridcast:postgres",
    "mechanism": "Postgres experienced transient unavailability, high latency, or connection exhaustion while ingestion attempted to persist demand data.",
    "statement": "Database backend failure."
  },
  {
    "root_cause": "service:gridcast:weather-vendor-wx-primary / service:gridcast:weather-vendor-wx-secondary",
    "mechanism": "The demand ingestion path depended on weather enrichment, and the primary weather vendor failed while the secondary fallback did not fail over cleanly.",
    "statement": "Weather vendor dependency failure with incomplete fallback."
  },
  {
    "root_cause": "k8s:gridcast:service:ingestion",
    "mechanism": "The Kubernetes Service selector temporarily matched no ready ingestion pods during a rolling update, so demand traffic could not reach a valid endpoint.",
    "statement": "Kubernetes routing or selector failure."
  }
]}
